DEFAULT_ANKI_CONNECT_URL = "http://127.0.0.1:8765"


@dataclass(frozen=True, slots=True)
class AnkiExportOptions:
    """Optional configuration for exporting generated decks to Anki."""

    deck_name: str
    url: str = DEFAULT_ANKI_CONNECT_URL
    api_key: str | None = None


@dataclass(frozen=True, slots=True)
class GenerateWorkflowRequest:
    """Request for the complete generation workflow."""

    generation_request: GenerateFlashcardsRequest
    language: str = "pt_BR"
    check_auth: bool = True
    anki: AnkiExportOptions | None = None


@dataclass(frozen=True, slots=True)
class CleanupRequest:
    """Request to remove all or recently created NotebookLM notebooks."""

    days: int | None = None
    check_auth: bool = True

    def __post_init__(self) -> None:
        if self.days is not None and self.days <= 0:
            raise ValueError("days must be positive")


@dataclass(frozen=True, slots=True)
class AuthStatus:
    """Result of checking NotebookLM authentication."""

    authenticated: bool
    message: str = ""


@dataclass(frozen=True, slots=True)
class MergeDetails:
    """Detailed row counts produced by a CSV merge operation."""

    rows_before: int
    rows_written: int
    duplicates_removed: int


@dataclass(frozen=True, slots=True)
class MergeOutcome:
    """Result of merging CSV files."""

    output_path: Path
    rows_written: int
    duplicates_removed: int = 0

    @property
    def rows_before(self) -> int:
        """Return the valid input row count before deduplication."""
        return self.rows_written + self.duplicates_removed


@dataclass(frozen=True, slots=True)
class CleanupOutcome:
    """Result of deleting selected NotebookLM notebooks."""

    deleted: int
    failed: int

    @property
    def succeeded(self) -> bool:
        """Return whether every selected notebook was deleted."""
        return self.failed == 0

"""UI-independent facade for complete application workflows."""

from __future__ import annotations

from collections.abc import Callable, Sequence
from typing import Protocol

from flashcards_generator.application.contracts import (
    CancellationToken,
    GenerationOutcome,
    ProgressReporter,
)
from flashcards_generator.application.csv_merger import CsvMerger
from flashcards_generator.application.dto.generate_request import (
    GenerateFlashcardsRequest,
)
from flashcards_generator.application.dto.merge_request import MergeCsvRequest
from flashcards_generator.application.dto.workflow import (
    AnkiExportOptions,
    AuthStatus,
    CleanupOutcome,
    CleanupRequest,
    MergeDetails,
    MergeOutcome,
)
from flashcards_generator.domain.entities import Deck
from flashcards_generator.domain.ports.anki_exporter import AnkiExporterPort


class GenerationWorkflowPort(Protocol):
    """Generate decks while publishing framework-neutral progress."""

    def generate(
        self,
        request: GenerateFlashcardsRequest,
        reporter: ProgressReporter,
        token: CancellationToken,
    ) -> GenerationOutcome:
        """Run one generation operation."""
        ...


class NotebookLMManagementPort(Protocol):
    """NotebookLM account and notebook-management operations."""

    def auth_status(self) -> AuthStatus:
        """Return the current authentication status."""
        ...

    def login(self) -> AuthStatus:
        """Run the provider login flow and return its resulting status."""
        ...

    def set_language(self, language: str) -> bool:
        """Set the provider output language."""
        ...

    def cleanup(self, *, days: int | None) -> CleanupOutcome:
        """Delete notebooks selected by age, or all when days is None."""
        ...


AnkiExporterFactory = Callable[[AnkiExportOptions], AnkiExporterPort]
MergeOperation = Callable[[MergeCsvRequest], int | MergeDetails]


class ApplicationWorkflows:
    """Single application facade shared by command-line and graphical UIs."""

    def __init__(
        self,
        generation: GenerationWorkflowPort,
        notebooklm: NotebookLMManagementPort,
        *,
        merge_operation: MergeOperation = CsvMerger.merge_detailed,
        anki_exporter_factory: AnkiExporterFactory | None = None,
    ) -> None:
        self._generation = generation
        self._notebooklm = notebooklm
        self._merge_operation = merge_operation
        self._anki_exporter_factory = anki_exporter_factory

    def generate(
        self,
        request: GenerateFlashcardsRequest,
        reporter: ProgressReporter,
        token: CancellationToken,
    ) -> GenerationOutcome:
        """Generate flashcards through the configured application operation."""
        if request.language.strip() and not self.set_language(
            request.language
        ):
            raise RuntimeError("Unable to set NotebookLM output language")
        return self._generation.generate(request, reporter, token)

    def merge(self, request: MergeCsvRequest) -> MergeOutcome:
        """Merge CSV files and return both the path and row count."""
        result = self._merge_operation(request)
        details = (
            MergeDetails(result, result, 0)
            if isinstance(result, int)
            else result
        )
        return MergeOutcome(
            output_path=request.folder_path / request.output_filename,
            rows_written=details.rows_written,
            duplicates_removed=details.duplicates_removed,
        )

    def auth_status(self) -> AuthStatus:
        """Return the current NotebookLM authentication status."""
        return self._notebooklm.auth_status()

    def login(self) -> AuthStatus:
        """Run NotebookLM login and return the resulting status."""
        return self._notebooklm.login()

    def set_language(self, language: str) -> bool:
        """Set the NotebookLM output language."""
        return self._notebooklm.set_language(language)

    def cleanup(
        self,
        request: CleanupRequest,
        *,
        confirmed: bool = False,
    ) -> CleanupOutcome:
        """Delete selected notebooks, requiring confirmation for delete-all."""
        if request.days is None and not confirmed:
            raise ValueError("cleanup-all requires explicit confirmation")
        if request.check_auth and not self.auth_status().authenticated:
            raise PermissionError("NotebookLM authentication is required")
        return self._notebooklm.cleanup(days=request.days)

    def cleanup_all(self, *, confirmed: bool) -> CleanupOutcome:
        """Delete every notebook only after explicit caller confirmation."""
        return self.cleanup(CleanupRequest(), confirmed=confirmed)

    def export_to_anki(
        self,
        decks: Sequence[Deck],
        options: AnkiExportOptions,
    ) -> int:
        """Export generated decks through the configured Anki port."""
        if self._anki_exporter_factory is None:
            raise RuntimeError("Anki export is not configured")
        exporter = self._anki_exporter_factory(options)
        return sum(exporter.export(deck) for deck in decks)

"""Generated card and CSV result presentation."""

from __future__ import annotations

import shutil
import subprocess
from collections.abc import Callable, Iterable
from pathlib import Path

from textual import on
from textual.app import ComposeResult
from textual.containers import Horizontal, Vertical
from textual.widgets import Button, Label, Static

from flashcards_generator.domain.entities import Deck

ResultsAction = Callable[[], None]


class ResultsPanel(Vertical):
    """Present generated cards and provide safe result actions."""

    def __init__(
        self,
        *,
        on_merge: ResultsAction | None = None,
        on_new_generation: ResultsAction | None = None,
        id: str | None = None,
    ) -> None:
        super().__init__(id=id, classes="workflow-panel")
        self._csv_path: Path | None = None
        self._on_merge = on_merge
        self._on_new_generation = on_new_generation

    def compose(self) -> ComposeResult:
        yield Label("Results", classes="workflow-title")
        yield Static("No completed run", id="results-summary")
        yield Static("No generated cards yet", id="results-cards")
        yield Static("No CSV output yet", id="results-csv")
        yield Static("No preview yet", id="results-preview")
        with Horizontal(classes="action-row"):
            yield Button("Copy CSV", id="results-copy")
            yield Button("Open CSV", id="results-open")
            yield Button("Merge", id="results-merge")
            yield Button("New generation", id="results-new")
        yield Static("", id="results-action-status")

    def show_decks(self, decks: Iterable[Deck]) -> None:
        """Render cards without changing the underlying domain models."""
        materialized = tuple(decks)
        lines = self._deck_lines(materialized)
        preview = self._card_preview(materialized)
        self.query_one("#results-cards", Static).update(
            "\n".join(lines) if lines else "No generated cards"
        )
        total_cards = sum(deck.total_cards for deck in materialized)
        self.query_one("#results-summary", Static).update(
            f"{len(materialized)} deck(s), {total_cards} card(s)"
        )
        self.query_one("#results-preview", Static).update(
            "\n".join(preview) if preview else "No card preview"
        )

    @staticmethod
    def _deck_lines(decks: tuple[Deck, ...]) -> list[str]:
        return [f"{deck.name}: {deck.total_cards} card(s)" for deck in decks]

    @staticmethod
    def _card_preview(decks: tuple[Deck, ...]) -> list[str]:
        return [
            f"{card.front} -> {card.back}"
            for deck in decks
            for card in deck.flashcards[:5]
        ]

    def show_csv(
        self,
        output_path: Path,
        rows_written: int,
        *,
        rows_before: int | None = None,
        duplicates_removed: int | None = None,
    ) -> None:
        """Render the service-provided output path and row counts."""
        self._csv_path = output_path
        summary = f"{output_path.name} - {rows_written} row(s)"
        if rows_before is not None and duplicates_removed is not None:
            summary += (
                f" ({rows_before} before, "
                f"{duplicates_removed} duplicate(s) removed)"
            )
        self.query_one("#results-csv", Static).update(summary)

    def show_csv_paths(self, paths: Iterable[Path]) -> None:
        """Render CSV paths returned by a completed generation."""
        values = tuple(paths)
        if values:
            self._csv_path = values[0]
            self.query_one("#results-csv", Static).update(
                "\n".join(str(path) for path in values)
            )

    def show_generation_summary(
        self,
        *,
        discovered: int,
        completed: int,
        skipped: int,
        failed: int,
        elapsed_seconds: float,
    ) -> None:
        """Render machine-consumable source counts and elapsed time."""
        self.query_one("#results-summary", Static).update(
            f"{completed}/{discovered} source(s), {skipped} skipped, "
            f"{failed} failed, {elapsed_seconds:.1f}s"
        )

    @on(Button.Pressed)
    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Handle result actions without embedding application workflows."""
        button_id = event.button.id
        if self._handle_navigation_action(button_id):
            return
        if button_id == "results-copy":
            self._copy_csv()
        elif button_id == "results-open":
            self._open_csv()

    def _handle_navigation_action(self, button_id: str | None) -> bool:
        actions = {
            "results-merge": self._on_merge,
            "results-new": self._on_new_generation,
        }
        if button_id not in actions:
            return False
        action = actions[button_id]
        if action is not None:
            self.call_after_refresh(action)
        return True

    def _copy_csv(self) -> None:
        if self._csv_path is None:
            self._set_action_status("No CSV available")
            return
        arguments = self._clipboard_arguments()
        if arguments is None:
            self._set_action_status("Clipboard command unavailable")
            return
        try:
            subprocess.run(
                arguments,
                input=self._csv_path.read_text(encoding="utf-8"),
                text=True,
                check=False,
                timeout=5,
            )
        except (OSError, subprocess.SubprocessError):
            self._set_action_status("Unable to copy CSV")
        else:
            self._set_action_status("CSV copied")

    @staticmethod
    def _clipboard_arguments() -> list[str] | None:
        command = shutil.which("wl-copy") or shutil.which("xclip")
        if command is None:
            return None
        arguments = [command]
        if command.endswith("xclip"):
            arguments.extend(["-selection", "clipboard"])
        return arguments

    def _open_csv(self) -> None:
        if self._csv_path is None:
            self._set_action_status("No CSV available")
            return
        opener = shutil.which("xdg-open")
        if opener is None:
            self._set_action_status("xdg-open unavailable")
            return
        try:
            subprocess.run(
                [opener, str(self._csv_path)],
                check=False,
                timeout=5,
            )
        except (OSError, subprocess.SubprocessError):
            self._set_action_status("Unable to open CSV")
        else:
            self._set_action_status("Open command sent")

    def _set_action_status(self, message: str) -> None:
        self.query_one("#results-action-status", Static).update(message)

"""Reusable filesystem picker widgets."""

from __future__ import annotations

from collections.abc import Iterable
from pathlib import Path
from typing import ClassVar

from textual.app import ComposeResult
from textual.binding import Binding
from textual.containers import Vertical
from textual.message import Message
from textual.widgets import Button, DirectoryTree

from flashcards_generator.interfaces.tui.widgets.shortcut_input import (
    ShortcutInput as Input,
)


class DirectoryOnlyTree(DirectoryTree):
    """Directory tree that keeps empty and unusually named folders visible."""

    BINDINGS: ClassVar[
        list[Binding | tuple[str, str] | tuple[str, str, str]]
    ] = [
        *DirectoryTree.BINDINGS,
        Binding("backspace", "select_parent", "Parent"),
        Binding("home", "select_root", "Root"),
    ]

    def filter_paths(self, paths: Iterable[Path]) -> list[Path]:
        """Display directories only without normalizing their names."""
        return [path for path in paths if path.is_dir()]

    def action_select_parent(self) -> None:
        """Select the parent of the directory currently used as the root."""
        current = Path(self.path).expanduser().absolute()
        self._select_directory(current.parent)

    def action_select_root(self) -> None:
        """Select the filesystem root containing the current directory."""
        current = Path(self.path).expanduser().absolute()
        self._select_directory(Path(current.anchor))

    def _select_directory(self, path: Path) -> None:
        if path != self.path:
            self.post_message(self.DirectorySelected(self.root, path))


class SourcePicker(Vertical):
    """Path input paired with an optional directory browser."""

    class Selected(Message):
        """A directory was selected by the user."""

        def __init__(self, path: Path) -> None:
            super().__init__()
            self.path = path

    def __init__(
        self,
        path: Path | str = ".",
        *,
        input_id: str = "source-picker-path",
        id: str | None = None,
        label: str = "Browse directories",
    ) -> None:
        super().__init__(id=id, classes="source-picker")
        self._initial_path = Path(path)
        self._input_id = input_id
        self._label = label

    def compose(self) -> ComposeResult:
        """Render a path field and directory tree."""
        yield Input(
            str(self._initial_path),
            placeholder="Directory path",
            id=self._input_id,
        )
        yield Button(self._label, id="source-picker-browse", variant="default")
        yield DirectoryOnlyTree(
            self._tree_root(self._initial_path),
            id="source-picker-tree",
            classes="is-hidden",
        )

    @property
    def value(self) -> str:
        """Return the path exactly as displayed in the input."""
        return self.query_one(f"#{self._input_id}", Input).value

    def set_path(self, path: Path | str) -> None:
        """Set a path without stripping Unicode, spaces, or empty folders."""
        value = str(path)
        self.query_one(f"#{self._input_id}", Input).value = value
        tree = self.query_one("#source-picker-tree", DirectoryOnlyTree)
        tree.path = self._tree_root(Path(value))

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Toggle the compact directory browser."""
        if event.button.id == "source-picker-browse":
            self.query_one("#source-picker-tree").toggle_class("is-hidden")

    def on_directory_tree_directory_selected(
        self, event: DirectoryTree.DirectorySelected
    ) -> None:
        """Preserve the selected directory's exact platform representation."""
        self.set_path(event.path)
        self.post_message(self.Selected(event.path))

    @staticmethod
    def _tree_root(path: Path) -> Path:
        if path.exists() and path.is_dir():
            return path
        parent = path.parent
        return parent if parent.exists() else Path.cwd()

